#!/usr/bin/env node
// The JSON files in data/ are the source of truth. Browsers block fetch() over file://, so this script
// copies them verbatim into data/data.js (window.PW_DATA). Run after editing any JSON:  node tools/bundle-data.js
// `--check` writes nothing and exits 1 if a committed bundle differs from what the JSON would generate (used by CI).
const fs = require('fs'), path = require('path'), loadData = require('./load-data.js');
const check = process.argv.includes('--check');
let stale = 0;
function emit(rel, text, note) {
  const p = path.join(__dirname, '..', rel);
  if (check) { const cur = fs.existsSync(p) ? fs.readFileSync(p, 'utf8') : null; if (cur !== text) { stale++; console.log('STALE: ' + rel + ' (run node tools/bundle-data.js)'); } else console.log('ok: ' + rel); return; }
  fs.writeFileSync(p, text); console.log('wrote ' + rel + ' (' + text.length + ' bytes)' + (note || ''));
}
const d = loadData();
emit('data/data.js', '/* GENERATED by tools/bundle-data.js from data/*.json — do not edit by hand. */\nwindow.PW_DATA = ' + JSON.stringify(d) + ';\n', ' from ' + loadData.FILES.map(f => f + '.json').join(', '));

// Frozen v0.1 data for the legacy replay player (A006), loaded on demand by the browser only when a v0.1 file is imported.
const legacyDir = path.join(__dirname, '..', 'data', 'legacy', 'v0.1');
if (fs.existsSync(legacyDir)) {
  const ld = loadData(legacyDir);
  emit('data/legacy-data.js', '/* GENERATED by tools/bundle-data.js from data/legacy/v0.1/*.json — frozen v0.1 rules, do not edit. */\nwindow.PW_LEGACY_DATA = ' + JSON.stringify(ld) + ';\n');
}
if (check) process.exit(stale ? 1 : 0);
